<template>
    <Liquid v-if="conditionLiquid?.start && exporting" :data="conditionLiquid.start"></Liquid>
    <div
        v-if="!exporting && !inGrid"
        class="drop__block--placeholder"
        :class="['drop__block_' + index, { 'ecom-drag-current': currentDrag }]"
        @mouseenter="overBlock"
    >
        <div class="drop__block--placeholder-body"></div>
    </div>
    <div
        v-bind="blockAttrs"
        @mouseenter="overBlock"
        @mouseleave="outBlock"
        @contextmenu.stop="rightClickMenu"
        @click.stop="activeBlock"
        :class="{ 'ecom_current-edit': !exporting && isEditing, 'ecom-grid-item': exporting }"
    >
        <FreeformBlock
            v-if="data.name === 'freeform_block'"
            :data="data"
            :deep="deep"
            :index="index"
            :section_id="section_id"
            :breadcrumb="breadcrumb"
            :dragParent="dragParent"
            :inGrid="inGrid"
            :control="control"
        />
        <Row
            v-else-if="block.row"
            :section_id="section_id"
            ref="blockElement"
            :data="block.row"
            :deep="deep + 1"
            :index="index"
            :breadcrumb="`${breadcrumb}/${data?.id}`"
            :dragParent="dragParent"
            :inGrid="true"
        />
        <component
            :is="block.group.element + 'Element'"
            v-else-if="block.group"
            ref="blockElement"
            :data="block.group"
            :key="refreshKey"
            :deep="deep"
            :index="index"
            :inGrid="true"
            :breadcrumb="!exporting ? `${breadcrumb}/${data?.id}` : null"
        />
        <template v-else>
            <component
                :is="checkExtensionNotInstall ? checkExtensionNotInstall : block.name + 'Element'"
                ref="blockElement"
                :key="refreshKey"
                :data="block"
                :deep="deep"
                :breadcrumb="!exporting ? `${breadcrumb}/${data?.id}` : null"
                :inGrid="true"
                :section_id="section_id"
            />
        </template>
    </div>
    <div
        v-if="!exporting"
        :class="{ 'ecom-drag-current': currentDrag }"
        class="drop__block--placeholder"
        @mouseenter="overBlock"
    >
        <div class="drop__block--placeholder-body"></div>
    </div>
    {{ exporting === true && conditionLiquid?.start ? conditionLiquid?.end : "" }}
</template>

<script lang="ts">
import { Core, Liquid, blockMixin } from "@/mixins";
import { allComponents, componentName, loadComponent } from "@/utils/helpers";
import { getOptionsGrid } from "./configElement"; // config element in grid layout
import FreeformBlock from "./FreeformBlock.vue";
export default {
    name: "BlockGrid",
    mixins: [Core, Liquid, blockMixin],
    components: {
        FreeformBlock,
        ...allComponents()
    },
    props: {
        data: {
            type: Object,
            default() {
                return {
                    name: "empty"
                };
            }
        },
        deep: {
            type: Number,
            default: 0
        },
        index: {
            type: Number,
            default: 0
        },
        control: {
            type: Boolean,
            default: true
        },
        gindex: {
            type: Number,
            default: 0
        },
        section_id: {
            type: String,
            default: ""
        },
        breadcrumb: {
            type: String,
            default: ""
        },
        dragParent: {
            type: Boolean,
            default: false
        },
        inGrid: {
            type: Boolean,
            default: false
        },
        inGroupGrid: {
            type: Boolean,
            default: false,
            required: false
        }
    },

    data(): object {
        return {
            is: "block",
            name: this.data.row ? "inner row" : this.data.group ? this.data.group.element : "block",
            over: false,
            dragging: false,
            placeholder: "top",
            refreshKey: "",
            isMounted: false,
            isDrag: false,
            space: 0,
            position: 0,
            paddingCurrentVal: 0,
            paddingPosition: "",
            isGrid: true
        };
    },

    computed: {
        blockAttrs() {
            const attrs = {
                ref: "wrapper",
                class: {
                    "ecom-animated": !this.exporting && !this.data.undoInBuilder,
                    "ecom-animation":
                        (this.data?.advanced?.animation_type ||
                            this.data?.group?.advanced?.animation_type) &&
                        !this.data.undoInBuilder,
                    "ecom-block ecom-core core__block": true,
                    "ecom-block-active": this.isActive,
                    "ecom-ingrid-full-height": true,
                    "ecom-block-isDragPadding":
                        this.isActive && !this.isDragging && !this.block.group,
                    elmspace: !this.data?.advanced?.spacing?.margin?.top,
                    ...this.classes
                },
                "data-core-is": this.exporting ? null : this.block.row
                    ? this.deep === 2
                        ? "block"
                        : "row"
                    : this.block.group
                    ? "group"
                    : "block",
                ...this.attributes
            };

            if (this.scrollingAnimation) {
                attrs["ecom-scrolling-animation"] = this.scrollingAnimation;
            }

            if (this.data?.advanced?.animation_delay) {
                const delayValue = this.data.advanced.animation_delay.toString().replace(/ms$/, '');
                attrs["ec-delay"] = delayValue || 0;
            }

            return attrs;
        },
        grid() {
            return this.$parent.$parent;
        },

        checkExtensionNotInstall() {
            const itemName = componentName(this.data.name) + "Element";
            return Object.keys(allComponents()).includes(itemName)
                ? ""
                : "PlaceholderExtensionElement";
        },
        stack() {
            return this.findGridParent()?.stack || [];
        }
    },

    //Added by daniel
    updated() {
        if (
            this.block.hasRequestLiquid !== true &&
            Object.keys(this.$refs?.blockElement?.requestShopifyType ?? {}).length > 0 &&
            Object.keys(this.$refs?.blockElement?.liquids ?? {}).length > 0
        ) {
            this.block.hasRequestLiquid = true;
        }
        if (this.data.editOnMounted && this.$refs.blockElement) {
            delete this.data.editOnMounted;
            // this.editBlock();
            this.openPresetLibrary();
        }
    },

    mounted() {
        if (this.data.editOnMounted && this.$refs.blockElement) {
            delete this.data.editOnMounted;
            // this.editBlock();
            this.openPresetLibrary();
        }
        //Modify by daniel
        if (
            Object.keys(this.$refs?.blockElement?.requestShopifyType ?? {}).length > 0 &&
            Object.keys(this.$refs?.blockElement?.liquids ?? {}).length > 0
        ) {
            this.block.hasRequestLiquid = true;
        }
        if (this.block?.group && !this.block.id) {
            this.block.id = this.$helpers.randid();
        }
        if (this.block.group) {
            this.block.group.id = this.block.id;
        }
        //this.stacks[this.data.id] = this;
        const style = this.data.style;
        if (style?.iconGeneral?.iconFontSize) {
            this.data.style.iconGeneral.iconFontSize = "";
        }

        if (!this.data.layouts) this.data.layouts = {};
        if (!this.data.layouts.options) this.data.layouts.options = {};
        // this.data.layouts.options = getOptionsGrid(this.data).options;
        this.instanceStore.register(this.data.id, this);
        this.isMounted = true;
    },

    methods: {
        outBlock() {
            if (!this.isFullScreen) {
                if (this._group) {
                    this._group.over = true;
                } else if (this._column) {
                    this._column.over = true;
                    if (this._row) {
                        this._row.over = true;
                    } else if (this._section) {
                        this._section.over = true;
                    }
                }
                clearTimeout(this.timmer);
                this.timmer = setTimeout(() => {
                    this.over = false;
                    let grid = this.$parent?.$parent?.$parent?.$parent;
                    if (
                        grid &&
                        grid.is === "grid" &&
                        grid.over &&
                        this.dragCurrent &&
                        this.dragCurrent.is != "column" &&
                        this.dragCurrent.is != "section"
                    ) {
                        this.$store.commit("builder/setDropTo", grid);
                    }
                }, 50);
            }
        },
        updateGridItemFromContent() {
            // Kiểm tra xem có blockElement không
            if (!this.$refs.blockElement || !this.$refs.blockElement.$el) return;

            // Lấy kích thước thực tế của blockElement
            const element = this.$refs.blockElement.$el;
            const rect = element.getBoundingClientRect();

            const parent = this.grid;
            // Nếu tìm thấy grid item, cập nhật kích thước
            if (parent) {
                // Chuyển đổi từ px sang đơn vị grid
                const grid = this.findGridParent();
                if (!grid) return;

                const colWidth = grid.calcColWidth();
                const rowHeight = grid.rowHeight;

                // Tính toán w, h mới dựa trên kích thước thực tế
                const newW = Math.ceil((rect.width + grid.marginX) / (colWidth + grid.marginX));
                const newH = Math.ceil((rect.height + grid.marginY) / (rowHeight + grid.marginY));

                // Chỉ cập nhật nếu kích thước thay đổi
                if (newW !== parent.innerW || newH !== parent.innerH) {
                    // Emit sự kiện để grid item biết cần thay đổi kích thước
                    parent.eventBus.emit("content-resize", {
                        i: this.data.id,
                        w: newW,
                        h: newH
                    });
                }
            }
        },

        findGridParent() {
            let parent = this.$parent;
            while (parent && parent.$options.name !== "Grid") {
                parent = parent.$parent;
            }
            return parent;
        },
        duplicate() {
            if (!this.$refs?.blockElement) return;

            // Lấy tham chiếu đến grid và blocks
            const grid = this.findGridParent();
            if (!grid || !grid.data || !grid.data.blocks) {
                console.error("Không tìm thấy grid hoặc blocks trong grid");
                return;
            }

            try {
                // Deep clone dữ liệu block
                const clone = this.cloneData();

                // Tạo ID mới
                clone.id = this.$helpers.randid();

                // Cập nhật title nếu có
                if (clone.title) {
                    clone.title = clone.title.replace(/\(([\d]*)\)|$/, (...m) => {
                        if (m[1]) return "(" + (parseInt(m[1]) + 1) + ")";
                        else return "(1)";
                    });
                }

                const containerWidth = grid?.containerWidth || grid?.width || 1200;

                // ✅ CALCULATE Z-INDEX FOR DUPLICATED BLOCK
                const newZIndex = this.calculateNextZIndex(grid);

                // Cập nhật layout cho tất cả breakpoints với vị trí hợp lý
                if (clone.layouts) {
                    Object.keys(clone.layouts).forEach((breakpoint) => {
                        if (
                            ["desktop", "tablet", "mobile"].includes(breakpoint) &&
                            clone.layouts[breakpoint]
                        ) {
                            // Lấy giá trị hiện tại
                            const currentLeft = parseFloat(clone.layouts[breakpoint].left); // %
                            const currentWidth = parseFloat(clone.layouts[breakpoint].width); // px
                            const currentTop = parseFloat(clone.layouts[breakpoint].top); // px

                            // Tính phần trăm chiếm dụng của width
                            const widthPercent = (currentWidth / containerWidth) * 100;

                            // Tính không gian còn lại bên phải
                            const spaceRight = 100 - (currentLeft + widthPercent);

                            // Kiểm tra không gian và quyết định dịch chuyển
                            if (spaceRight >= 2) {
                                // Nếu bên phải đủ không gian, dịch sang phải 2%
                                clone.layouts[breakpoint].left = currentLeft + 2;
                            } else if (currentLeft >= 2) {
                                // Nếu bên trái đủ không gian, dịch sang trái 2%
                                clone.layouts[breakpoint].left = currentLeft - 2;
                            }
                            // Nếu không đủ không gian bên nào, giữ nguyên vị trí ngang

                            // Luôn dịch chuyển xuống dưới 20px
                            clone.layouts[breakpoint].top = currentTop + 20;

                            // ✅ SET NEW Z-INDEX FOR DUPLICATED BLOCK
                            clone.layouts[breakpoint].zindex = newZIndex;
                        }
                    });
                }

                // ✅ ENSURE Z-INDEX IS SET EVEN IF LAYOUTS DOESN'T EXIST
                if (!clone.layouts) {
                    clone.layouts = {
                        desktop: { zindex: newZIndex },
                        tablet: { zindex: newZIndex },
                        mobile: { zindex: newZIndex }
                    };
                }

                // Thêm vào blocks
                const index = grid.data.blocks.findIndex((b) => b.id === this.data.id);
                if (index > -1) {
                    grid.data.blocks.splice(index + 1, 0, clone);
                } else {
                    grid.data.blocks.push(clone);
                }

                grid.handleUndoRedoGridItem(clone, "added");

                // Emit sự kiện để cập nhật grid
                this.eventBus.emit("update-grid-layout", {
                    sectionId: this.section_id,
                    blocks: grid.data.blocks
                });

                console.log(
                    `✅ Duplicated block ${this.data.id} -> ${clone.id} with z-index: ${newZIndex}`
                );
            } catch (error) {
                console.error("Lỗi khi duplicate:", error);
            }
        },

        // Calculate next Z-Index for duplicate
        calculateNextZIndex(grid) {
            let maxZIndex = 9; // Bắt đầu từ 9, vì có duplicate thì sẽ là 10

            // Duyệt qua tất cả blocks để tìm z-index cao nhất
            grid.data.blocks.forEach((block) => {
                if (!block.layouts) return;

                // Kiểm tra z-index trong tất cả các screen layouts
                Object.keys(block.layouts).forEach((screen) => {
                    if (screen === "options") return; // Skip options key

                    const layout = block.layouts[screen];
                    if (
                        layout &&
                        layout.zindex !== undefined &&
                        layout.zindex !== null &&
                        layout.zindex !== ""
                    ) {
                        const currentZIndex = parseInt(layout.zindex);
                        if (!isNaN(currentZIndex)) {
                            maxZIndex = Math.max(maxZIndex, currentZIndex);
                        }
                    }
                });
            });

            // Trả về max z-index + 1
            return maxZIndex + 1;
        }
    }
};
</script>
