<!-- FreeformBlock.vue - Chỉ tạo container, không positioning -->
<template>
    <div
        ref="freeformContainer"
        class="freeform-block"
        :class="containerClasses"
        :style="containerStyle"
        :data-id="data.id"
        @mouseenter="onMouseEnter"
        @mouseleave="onMouseLeave"
        @mouseup="onMouseUp"
        @mousemove="onMouseMove"
        @click.stop="onClick"
    >
        <!-- Nested items container -->
        <div class="freeform-content">
            <!-- Render nested blocks bên trong freeform -->
            <template v-for="block in nestedBlocks" :key="block.id">
                <GridItem
                    :left="getItemLayout(block).left"
                    :top="getItemLayout(block).top"
                    :width="getItemLayout(block).width"
                    :height="getItemLayout(block).height"
                    :zindex="getItemLayout(block).zindex || 1"
                    :i="block.id"
                    :rotation="getItemLayout(block).rotation || 0"
                    :options="getItemOptions(block)"
                    :section-id="section_id"
                    :grid-container-width="containerWidth"
                    :in-freeform="true"
                    :freeform-id="data.id"
                    :is-draggable="true"
                    :is-resizable="true"
                    @move="onItemMove"
                    @moved="onItemMoved"
                    @resize="onItemResize"
                    @resized="onItemResized"
                    @rotated="onItemRotated"
                >
                    <!-- Render actual block content -->
                    <BlockGridElement
                        :data="block"
                        :deep="deep + 1"
                        :index="getBlockIndex(block.id)"
                        :control="true"
                        :section_id="section_id"
                        :breadcrumb="`${breadcrumb}/${block.id}`"
                        :dragParent="false"
                        :inGrid="false"
                        :inFreeform="true"
                        :freeformId="data.id"
                    />
                </GridItem>
            </template>
        </div>

        <!-- Drop indicator khi đang drag -->
        <div
            v-if="showDropIndicator"
            class="drop-indicator"
            :style="dropIndicatorStyle"
        >
            Drop here
        </div>

        <!-- Empty state -->
        <div v-if="isEmpty" class="empty-state">
            <div class="empty-content">
                <span class="empty-icon">📦</span>
                <span class="empty-text">Drag elements here</span>
                <span class="empty-subtitle">Freeform container</span>
            </div>
        </div>

        <!-- Info khi có items -->
        <div v-if="!isEmpty && isActive" class="freeform-info">
            {{ nestedBlocks.length }} items
        </div>
    </div>
</template>

<script>
import { defineAsyncComponent } from "vue";
import LoadingComponent from "./Loading.vue";
import { GridItem } from "@/plugins/vue-grid-layout/index";
import { ensureNumericValue } from "@/plugins/vue-grid-layout/helpers/utils";

export default {
    name: "FreeformBlock",
    components: {
        GridItem,
        BlockGridElement: defineAsyncComponent({
            loader: () => import("./BlockGrid.vue"),
            loadingComponent: LoadingComponent,
            delay: 0,
            timeout: 60000
        })
    },
    props: {
        data: {
            type: Object,
            required: true
        },
        deep: {
            type: Number,
            default: 0
        },
        index: {
            type: Number,
            default: 0
        },
        section_id: {
            type: String,
            required: true
        },
        breadcrumb: {
            type: String,
            default: ""
        },
        dragParent: {
            type: Boolean,
            default: true
        },
        inGrid: {
            type: Boolean,
            default: false
        },
        control: {
            type: Boolean,
            default: true
        }
    },
    inject: ["eventBus", "instanceStore", "exporting"],
    data() {
        return {
            // State
            isActive: false,
            isMouseInside: false,

            // Drop state
            mousePosition: { x: 0, y: 0 },

            // Container dimensions
            containerWidth: 600,
            containerHeight: 400
        };
    },
    computed: {
        // Grid system integration
        currentScreen() {
            return this.$store.getters["builder/screen"];
        },

        dragCurrent() {
            return this.$store.getters["builder/dragCurrent"];
        },

        isDragging() {
            return this.$store.getters["builder/isDragging"];
        },

        dropTo() {
            return this.$store.getters["builder/dropTo"];
        },

        isCurrentDropTarget() {
            return this.dropTo === this;
        },

        // Freeform specific
        nestedBlocks() {
            return this.data.blocks || [];
        },

        isEmpty() {
            return this.nestedBlocks.length === 0;
        },

        canAcceptDrop() {
            if (!this.isDragging || !this.dragCurrent) return false;

            // Không cho phép drop freeform vào freeform
            if (this.dragCurrent.data?.name === 'freeform_block') return false;

            // Không cho phép drop item từ chính freeform này
            if (this.dragCurrent.inFreeform && this.dragCurrent.freeform_id === this.data.id) {
                return false;
            }

            return true;
        },

        showDropIndicator() {
            return this.isDragging && this.canAcceptDrop && this.isMouseInside;
        },

        // Styling
        containerClasses() {
            return {
                'freeform-active': this.isActive,
                'freeform-empty': this.isEmpty,
                'freeform-can-drop': this.canAcceptDrop && this.isDragging,
                'freeform-drop-target': this.isCurrentDropTarget,
                'freeform-mouse-inside': this.isMouseInside && this.isDragging
            };
        },

        containerStyle() {
            return {
                minHeight: this.isEmpty ? '200px' : '100px',
                position: 'relative',
                width: '100%',
                height: '100%'
            };
        },

        dropIndicatorStyle() {
            return {
                position: 'absolute',
                left: `${this.mousePosition.x - 40}px`,
                top: `${this.mousePosition.y - 15}px`,
                width: '80px',
                height: '30px',
                backgroundColor: '#007cba',
                color: 'white',
                borderRadius: '4px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '12px',
                fontWeight: '500',
                pointerEvents: 'none',
                zIndex: 1000,
                opacity: 0.9
            };
        }
    },
    mounted() {
        if (this.exporting) return;

        // Register với instance store
        this.instanceStore.register(this.data.id, this);

        // Set properties để tương thích với drag system
        this.is = "freeform";
        this.canDrop = true;

        // Update container size
        this.updateContainerSize();

        // Listen to events
        this.eventBus.on("freeform-item-added", this.onItemAdded);
        this.eventBus.on("freeform-item-removed", this.onItemRemoved);

        window.addEventListener('resize', this.updateContainerSize);

        console.log(`✅ FreeformBlock mounted: ${this.data.id}`, {
            nestedBlocks: this.nestedBlocks.length,
            containerSize: { width: this.containerWidth, height: this.containerHeight }
        });
    },
    beforeUnmount() {
        if (this.exporting) return;

        this.instanceStore.unregister?.(this.data.id);
        this.eventBus.off("freeform-item-added", this.onItemAdded);
        this.eventBus.off("freeform-item-removed", this.onItemRemoved);
        window.removeEventListener('resize', this.updateContainerSize);
    },
    methods: {
        // Mouse event handlers
        onMouseEnter(e) {
            this.isActive = true;
            this.isMouseInside = true;

            // Set as drop target nếu đang drag
            if (this.isDragging && this.canAcceptDrop) {
                this.$store.commit("builder/setDropTo", this);
                console.log(`🎯 Freeform set as drop target: ${this.data.id}`);
            }
        },

        onMouseLeave(e) {
            this.isActive = false;
            this.isMouseInside = false;

            // Clear drop target
            if (this.isCurrentDropTarget) {
                setTimeout(() => {
                    if (!this.isMouseInside) {
                        this.$store.commit("builder/setDropTo", null);
                    }
                }, 50);
            }
        },

        onMouseMove(e) {
            if (!this.isMouseInside) return;

            // Update mouse position cho drop indicator
            const rect = this.$refs.freeformContainer?.getBoundingClientRect();
            if (rect) {
                this.mousePosition = {
                    x: e.clientX - rect.left,
                    y: e.clientY - rect.top
                };
            }
        },

        onMouseUp(e) {
            // Handle drop khi mouse up + đang drag + mouse inside + là drop target
            if (this.isDragging && this.canAcceptDrop && this.isMouseInside && this.isCurrentDropTarget) {
                console.log(`🎯 Handling drop in freeform: ${this.data.id}`);
                this.handleDrop(e);
            }
        },

        onClick(e) {
            // Set active element
            this.$store.commit("builder/setActiveElement", this);
            this.$store.commit("builder/setEditingElement", this);
            e.stopPropagation();
        },

        // Drop handling
        handleDrop(e) {
            if (!this.dragCurrent) {
                console.warn("No drag current found");
                return;
            }

            try {
                // Get dropped data
                const droppedData = this.dragCurrent.dropOut();
                if (!droppedData) {
                    console.error("Cannot get dropped data");
                    return;
                }

                console.log("🎯 Processing drop:", {
                    itemId: droppedData.id,
                    itemName: droppedData.name,
                    freeformId: this.data.id,
                    position: this.mousePosition
                });

                // Clone data để tránh mutation
                const blockData = JSON.parse(JSON.stringify(droppedData));

                // Generate ID nếu cần
                if (!blockData.id) {
                    blockData.id = this.generateId();
                }

                // Setup layouts nếu chưa có
                if (!blockData.layouts) {
                    blockData.layouts = {};
                }

                // Get current layout for sizing reference
                const currentLayout = blockData.layouts[this.currentScreen] ||
                                      blockData.layouts.desktop ||
                                      { width: 200, height: 100 };

                // Convert to pixel values và ensure reasonable sizing
                let itemWidth = this.ensurePixelValue(currentLayout.width || 200);
                let itemHeight = this.ensurePixelValue(currentLayout.height || 100);

                // Constrain size to container
                itemWidth = Math.min(itemWidth, this.containerWidth - 20);
                itemHeight = Math.min(itemHeight, this.containerHeight - 20);
                itemWidth = Math.max(itemWidth, 50); // Minimum width
                itemHeight = Math.max(itemHeight, 30); // Minimum height

                // Calculate final position (constrain within container)
                const finalX = Math.max(0, Math.min(this.mousePosition.x, this.containerWidth - itemWidth));
                const finalY = Math.max(0, Math.min(this.mousePosition.y, this.containerHeight - itemHeight));

                // Create freeform layout for current screen
                const freeformLayout = {
                    left: finalX,        // pixel value
                    top: finalY,         // pixel value
                    width: itemWidth,    // pixel value
                    height: itemHeight,  // pixel value
                    zindex: this.getNextZIndex(),
                    rotation: currentLayout.rotation || 0
                };

                // Ensure layouts object exists for all screens
                if (!blockData.layouts.desktop) blockData.layouts.desktop = {};
                if (!blockData.layouts.tablet) blockData.layouts.tablet = {};
                if (!blockData.layouts.mobile) blockData.layouts.mobile = {};

                // Update layout for current screen
                blockData.layouts[this.currentScreen] = freeformLayout;

                // Tạo layout tương ứng cho các screen khác nếu chưa có
                ['desktop', 'tablet', 'mobile'].forEach(screen => {
                    if (screen !== this.currentScreen && !blockData.layouts[screen].left) {
                        blockData.layouts[screen] = {
                            left: finalX,
                            top: finalY,
                            width: itemWidth,
                            height: itemHeight,
                            zindex: freeformLayout.zindex,
                            rotation: freeformLayout.rotation
                        };
                    }
                });

                // Set freeform properties
                blockData.inFreeform = true;
                blockData.freeform_id = this.data.id;

                // Clean up unnecessary properties
                delete blockData.hidden;
                if (blockData.group) {
                    delete blockData.group.hidden;
                }

                // Remove grid-specific properties nếu có
                if (blockData.x !== undefined) delete blockData.x;
                if (blockData.y !== undefined) delete blockData.y;
                if (blockData.w !== undefined) delete blockData.w;
                if (blockData.h !== undefined) delete blockData.h;

                // Add to freeform blocks
                if (!this.data.blocks) {
                    this.data.blocks = [];
                }
                this.data.blocks.push(blockData);

                console.log("✅ Item added to freeform:", {
                    itemId: blockData.id,
                    position: { x: finalX, y: finalY },
                    size: { width: itemWidth, height: itemHeight },
                    layout: freeformLayout,
                    totalItems: this.data.blocks.length
                });

                // Force reactivity update
                this.$forceUpdate();

                // Emit events
                this.eventBus.emit("freeform-item-added", {
                    freeformId: this.data.id,
                    itemId: blockData.id,
                    blockData: blockData,
                    position: { x: finalX, y: finalY }
                });

                // Add to history
                this.addToHistory("drop_item", blockData.id);

                // Cleanup drag state
                this.$store.commit("builder/resetDragging");
                this.$store.commit("builder/setActiveElement", null);
                this.$store.commit("builder/setDropTo", null);

            } catch (error) {
                console.error("❌ Error handling drop:", error);
            }
        },

        // Item layout methods - CHỈ TRẢ VỀ DATA, KHÔNG TẠO STYLE
        getItemLayout(block) {
            const screen = this.currentScreen;
            const layout = block.layouts?.[screen] || block.layouts?.desktop || {};

            // Đảm bảo tất cả values đều là numbers (pixel) cho freeform
            return {
                left: ensureNumericValue(layout.left) || 0,          // pixel
                top: ensureNumericValue(layout.top) || 0,           // pixel
                width: ensureNumericValue(layout.width) || 200,     // pixel
                height: ensureNumericValue(layout.height) || 100,   // pixel
                zindex: ensureNumericValue(layout.zindex) || 1,
                rotation: ensureNumericValue(layout.rotation) || 0
            };
        },

        // XOÁ getItemStyle method - không cần nữa vì GridItem sẽ tự tạo style

        getItemOptions(block) {
            return {
                resize: {
                    conner: true,
                    x: true,
                    y: true
                },
                ratioSize: false,
                autoHeight: false
            };
        },

        // Item event handlers
        onItemMove(itemId, newLeft, newTop) {

        },

        onItemMoved(itemId, newLeft, newTop) {
            const block = this.nestedBlocks.find(b => b.id === itemId);
            if (block) {
                if (!block.layouts[this.currentScreen]) {
                    block.layouts[this.currentScreen] = {};
                }

                // Trong freeform, lưu trực tiếp pixel values
                block.layouts[this.currentScreen].left = ensureNumericValue(newLeft);
                block.layouts[this.currentScreen].top = ensureNumericValue(newTop);

                console.log(`✅ Item moved: ${itemId}`, {
                    newLeft: ensureNumericValue(newLeft),
                    newTop: ensureNumericValue(newTop)
                });
                this.addToHistory("move_item", itemId);
            }
        },

        onItemResize(itemId, newHeight, newWidth) {

        },

        onItemResized(itemId, newHeight, newWidth, newLeft, newTop) {
            const block = this.nestedBlocks.find(b => b.id === itemId);
            if (block) {
                if (!block.layouts[this.currentScreen]) {
                    block.layouts[this.currentScreen] = {};
                }

                const layout = block.layouts[this.currentScreen];

                // Lưu pixel values
                if (newLeft !== undefined) layout.left = ensureNumericValue(newLeft);
                if (newTop !== undefined) layout.top = ensureNumericValue(newTop);
                if (newWidth !== undefined) layout.width = ensureNumericValue(newWidth);
                if (newHeight !== undefined) layout.height = ensureNumericValue(newHeight);

                console.log(`✅ Item resized: ${itemId}`, {
                    newWidth: ensureNumericValue(newWidth),
                    newHeight: ensureNumericValue(newHeight),
                    newLeft: ensureNumericValue(newLeft),
                    newTop: ensureNumericValue(newTop)
                });
                this.addToHistory("resize_item", itemId);
            }
        },

        onItemRotated(itemId, newRotation) {
            const block = this.nestedBlocks.find(b => b.id === itemId);
            if (block) {
                if (!block.layouts[this.currentScreen]) {
                    block.layouts[this.currentScreen] = {};
                }
                block.layouts[this.currentScreen].rotation = ensureNumericValue(newRotation);

                console.log(`✅ Item rotated: ${itemId}`, { newRotation });
                this.addToHistory("rotate_item", itemId);
            }
        },

        // Utility methods
        getBlockIndex(itemId) {
            return this.nestedBlocks.findIndex(b => b.id === itemId);
        },

        getNextZIndex() {
            if (this.nestedBlocks.length === 0) return 1;

            let maxZ = 0;
            this.nestedBlocks.forEach(block => {
                const layout = this.getItemLayout(block);
                if (layout.zindex > maxZ) {
                    maxZ = layout.zindex;
                }
            });
            return maxZ + 1;
        },

        ensurePixelValue(value) {
            if (typeof value === 'string' && value.includes('%')) {
                const percent = parseFloat(value);
                return Math.round((percent / 100) * this.containerWidth);
            }
            return ensureNumericValue(value);
        },

        generateId() {
            return `freeform-item-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
        },

        createDefaultLayouts() {
            return {
                desktop: { left: 0, top: 0, width: 200, height: 100, zindex: 1, rotation: 0 },
                tablet: { left: 0, top: 0, width: 180, height: 90, zindex: 1, rotation: 0 },
                mobile: { left: 0, top: 0, width: 160, height: 80, zindex: 1, rotation: 0 }
            };
        },

        updateContainerSize() {
            if (this.$refs.freeformContainer) {
                const rect = this.$refs.freeformContainer.getBoundingClientRect();
                this.containerWidth = rect.width || 600;
                this.containerHeight = rect.height || 400;
            }
        },

        addToHistory(action, itemId = null) {
            const payload = {
                type: "freeform",
                data: this.data,
                section_id: this.section_id,
                freeform_id: this.data.id,
                action: action
            };

            if (itemId) {
                payload.item_id = itemId;
            }

            this.$store.dispatch("history/addStack", payload);
        },

        // Event handlers
        onItemAdded(data) {
            if (data.freeformId === this.data.id) {
                console.log("Freeform item added:", data.itemId);
            }
        },

        onItemRemoved(data) {
            if (data.freeformId === this.data.id) {
                console.log("Freeform item removed:", data.itemId);
            }
        },

        // Public methods cho external usage
        removeItem(itemId) {
            const index = this.nestedBlocks.findIndex(b => b.id === itemId);
            if (index !== -1) {
                this.nestedBlocks.splice(index, 1);
                this.eventBus.emit("freeform-item-removed", {
                    freeformId: this.data.id,
                    itemId: itemId
                });
                this.addToHistory("remove_item", itemId);
            }
        },

        dropOut() {
            // Allow freeform block to be dragged out
            return this.data;
        }
    }
};
</script>
